int resolve_last_component(struct nameidata *nd, struct path *path) {
    struct dentry *dentry;
    int error;

    if (nd->flags & LOOKUP_RCU) {
        dentry = lookup_dcookie(nd);
        if (IS_ERR_OR_NULL(dentry))
            return PTR_ERR(dentry);

        path->dentry = dentry;
        path->mnt = nd->path.mnt;
        return 0;
    }

    dentry = nd->path.dentry;
    error = -ENOMEM;

    if (dentry->d_inode && S_ISLNK(dentry->d_inode->i_mode)) {
        dentry = lookup_symlink(dentry);
        if (IS_ERR(dentry))
            return PTR_ERR(dentry);
    }

    mutex_lock(&dentry->d_inode->i_mutex);
    dentry = lookup_one(nd->last.name, nd->last.len, dentry);
    if (IS_ERR(dentry)) {
        mutex_unlock(&dentry->d_inode->i_mutex);
        return PTR_ERR(dentry);
    }

    if (!dentry->d_inode) {
        mutex_unlock(&dentry->d_inode->i_mutex);
        return -ENOENT;
    }

    path->dentry = dentry;
    path->mnt = nd->path.mnt;
    mutex_unlock(&dentry->d_inode->i_mutex);
    return 0;
}

int resolve_last_component(struct nameidata *nd, struct path *path) {
    struct dentry *dentry;
    int error;

    if (nd->flags & LOOKUP_RCU) {
        dentry = lookup_one_len_rcu(nd->name, nd->path.dentry, nd->len);
        if (IS_ERR_OR_NULL(dentry))
            return PTR_ERR(dentry);

        path->dentry = dentry;
        path->mnt = nd->path.mnt;
        return 0;
    }

    dentry = d_lookup(nd->path.dentry, nd->name, nd->len);
    if (dentry) {
        path->dentry = dentry;
        path->mnt = nd->path.mnt;
        return 0;
    }

    dentry = d_alloc_name(nd->path.dentry, nd->name);
    if (!dentry)
        return -ENOMEM;

    path->dentry = dentry;
    path->mnt = nd->path.mnt;

    error = nd->path.mnt->mnt_sb->s_op->lookup(nd->path.dentry->d_inode, dentry);
    if (error) {
        dput(dentry);
        return error;
    }

    if (IS_ERR_OR_NULL(dentry->d_inode)) {
        if (IS_ERR(dentry->d_inode))
            return PTR_ERR(dentry->d_inode);

        dput(dentry);
        return -ENOENT;
    }

    return 0;
}

int resolve_last_component(struct nameidata *nd, struct path *path) {
    struct dentry *dentry;
    int error;

    if (nd->flags & LOOKUP_RCU) {
        rcu_read_lock();
        dentry = d_lookup(nd->path.dentry, nd->last.name, nd->last.len);
        if (dentry) {
            path->dentry = dentry;
            path->mnt = nd->path.mnt;
            rcu_read_unlock();
            return 0;
        }
        rcu_read_unlock();
    }

    mutex_lock(&nd->path.dentry->d_inode->i_mutex);
    dentry = d_lookup(nd->path.dentry, nd->last.name, nd->last.len);
    if (!dentry) {
        dentry = d_alloc_name(nd->path.dentry, nd->last.name);
        if (!dentry) {
            mutex_unlock(&nd->path.dentry->d_inode->i_mutex);
            return -ENOMEM;
        }
        error = nd->path.dentry->d_inode->i_op->lookup(nd->path.dentry->d_inode, dentry, nd->last.name, nd->last.len);
        if (error) {
            dput(dentry);
            mutex_unlock(&nd->path.dentry->d_inode->i_mutex);
            return error;
        }
    }

    path->dentry = dentry;
    path->mnt = nd->path.mnt;
    mutex_unlock(&nd->path.dentry->d_inode->i_mutex);
    return 0;
}

int resolve_last_component(struct nameidata *nd, struct path *path) {
    int error;

    if (nd->depth && nd->flags & LOOKUP_RCU) {
        struct dentry *dentry;

        dentry = nd->path.dentry;
        if (dentry->d_flags & DCACHE_NEED_AUTOMOUNT) {
            error = -ECHILD;
            if (nd->flags & LOOKUP_NO_AUTOMOUNT)
                return error;
        }

        error = lookup_last(nd, path);
        if (error)
            return error;

        if (path->dentry->d_flags & DCACHE_AUTOMOUNT)
            return -ECHILD;
    } else {
        error = lookup_last(nd, path);
        if (error)
            return error;

        if (path->dentry->d_flags & DCACHE_AUTOMOUNT) {
            error = -ECHILD;
            if (nd->flags & LOOKUP_NO_AUTOMOUNT)
                return error;
        }
    }

    return 0;
}

int resolve_last_component(struct nameidata *nd, struct path *path) {
    int error;

    if (nd->flags & LOOKUP_RCU) {
        struct dentry *dentry = lookup_one_len_rcu(nd->last.name, nd->path.dentry, nd->last.len);
        if (IS_ERR_OR_NULL(dentry))
            return PTR_ERR(dentry);
        path->dentry = dentry;
        path->mnt = nd->path.mnt;
        return 0;
    }

    error = mnt_want_write(nd->path.mnt);
    if (error)
        return error;

    {
        struct dentry *dentry = lookup_one(nd->last.name, nd->path.dentry, nd->last.len);
        if (IS_ERR(dentry)) {
            error = PTR_ERR(dentry);
            goto out;
        }

        if (!dentry->d_inode) {
            error = -ENOENT;
            goto out_put;
        }

        path->dentry = dentry;
        path->mnt = nd->path.mnt;
    }

    error = 0;

out_put:
    path_put(&nd->path);
out:
    mnt_drop_write(nd->path.mnt);
    return error;
}
